-   */
-  if ( (trailer_len & 3) == 3 )
-    return 0;
-
-  /* ... and if you have neither a time stamp nor a port stamp,
-   * you don't have a trailer
-   */
-  if ( (trailer_len & 3) == 0 && trailer_len < 8 )
+  if ( (trailer_len & 3) != 0 && (trailer_len & 3) != portstamp_len )
     return 0;

