+       */
       if (vssmonitoring_time.secs > 3600) {

         /* Check whether the timestamp in the PCAP header and the VSS-Monitoring
@@ -145,6 +163,16 @@ dissect_vssmonitoring(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void
        */
